#include <CGAL/linear_least_squares_fitting_3.h>
#include <list>

typedef CGAL::Exact_predicates_inexact_constructions_kernel Kernel;

Kernel::Plane_3 compute_best_fitting_plane(const std::list<Kernel::Point_3>& points) {
    if (points.empty()) {
        return Kernel::Plane_3(CGAL::ORIGIN, Kernel::Vector_3(0, 0, 1));
    }

    Kernel::Plane_3 plane;
    typename std::list<Kernel::Point_3>::const_iterator it = points.begin();
    linear_least_squares_fitting_3(points.begin(), points.end(), plane, CGAL::Dimension_tag<0>());
    return plane;
}

